[CmdletBinding(SupportsShouldProcess)]param()
$ErrorActionPreference='Stop';$startup=[Environment]::GetFolderPath('Startup');$shortcut=Join-Path $startup 'NEEWA Hermes Desktop.lnk';if($PSCmdlet.ShouldProcess($shortcut,'Remove startup shortcut')){Remove-Item -Force $shortcut -ErrorAction SilentlyContinue};$home=if($env:HERMES_HOME){$env:HERMES_HOME}else{Join-Path $env:LOCALAPPDATA 'hermes'};foreach($path in @((Join-Path $home 'desktop-plugins\neewa-command-center'),(Join-Path $home 'skins\neewa.yaml'))){if($PSCmdlet.ShouldProcess($path,'Remove NEEWA asset')){Remove-Item -Recurse -Force $path -ErrorAction SilentlyContinue}};$run='HKCU:\Software\Microsoft\Windows\CurrentVersion\Run';foreach($name in @('NEEWA-CuaDriver','NEEWA-WindowsWorker')){if($PSCmdlet.ShouldProcess($name,'Remove HKCU Run')){Remove-ItemProperty -Path $run -Name $name -ErrorAction SilentlyContinue}};Write-Host 'NEEWA assets and worker Run keys removed. Hermes data, credentials, sessions, Tailscale, and cua-driver binaries preserved. To remove cua-driver use the official GitHub uninstall.ps1.'
